begin;
do $install24$
declare changed integer;
begin
 update public.lessons set content=jsonb_set(content,'{phase_two_production}',$lesson24${"production_version": "2.4-owner-review-2026-10-10", "approval_status": "founder_review_not_published", "curriculum_version": "2.0", "lesson_id": "2.4", "primary_media": "audio", "title": "Choose assistants, automation and agents", "learner_promise": "Compare four ways to support your existing workflow, choose the least complex suitable pattern, and retain a bounded solution concept with human approval and a usable fallback.", "pacing": [{"key": "teaching", "label": "Four support patterns and human authority", "minutes": 15}, {"key": "worked_case", "label": "Routine invoice reminder and disputed payment", "minutes": 10}, {"key": "application", "label": "Comparison, bounded concept and feature check", "minutes": 25}, {"key": "verification", "label": "Sufficient support and retained human approval", "minutes": 10}], "outcomes": ["Compare no AI, assistant, rule-based automation and agent support for the same task.", "Choose the least complex suitable pattern and explain why the other three are less suitable.", "Separate support, recommendation, decision and approval.", "Define allowed actions, prohibited actions, human checkpoints and monitoring.", "Provide a stop and manual fallback route for missing or contradictory information.", "Verify technical claims against current official documentation before adoption and save the updated concept."], "teaching": [{"heading": "Compare one task under all four patterns", "paragraphs": ["Use the same input and reviewed result for each comparison. No AI may mean a person using a checklist, approved template or ordinary tool. An assistant responds to directed work; for your bounded concept, specify whether it only prepares a draft or recommendation. Automation follows defined triggers and rules. An agent may choose several actions within its permissions.", "Record fit, limits, permissions and review effort for all four. A simple task may not need AI. Do not assume that an agent label grants any specific capability. Keep expected gains separate from observed results."], "think_prompt": "Which exact part of your task needs flexible judgment, and which part already follows fixed rules?"}, {"heading": "Distinguish a routine reminder from an exception", "paragraphs": ["In the fictional case, the company allows a standard reminder only after confirming the invoice, unpaid status, recipient and absence of a dispute or payment arrangement. An ordinary checklist is the baseline. A fixed recurring path may suit ordinary automation; a varied draft may suit an assistant.", "An unusual dispute changes the route. Preserve conflicting information and send the case to the accounts coordinator. Do not infer that a missing dispute flag proves no dispute exists. Do not grant sending, payment, balance-changing or refund authority merely because a system could perform those actions."], "think_prompt": "What should stop if a customer says paid but the record says unpaid?"}, {"heading": "Make the authority boundary observable", "paragraphs": ["Support prepares information. A recommendation proposes an action with reasons. A decision selects the action. Approval permits it within the approver’s actual authority. Name the role and evidence required at each human checkpoint.", "Specify allowed inputs and actions, prohibited actions and access, monitoring owner and review rhythm, stop conditions, and manual fallback. Written instructions must be matched by actual tool access and settings before adoption. Today’s comparison is planning evidence, not authorization to connect or deploy."], "think_prompt": "Which action may the AI recommend while the authorized person retains the decision and approval?"}, {"heading": "Check the feature and update the concept", "paragraphs": ["Record the exact platform claim, official documentation title and URL, actual check date, supported behavior and limits. General documentation does not prove your account’s plan, connector, settings or tested behavior. If no platform is chosen, state that capabilities remain unverified and must be checked before adoption.", "For an optional documentation example, Microsoft Learn describes Power Automate triggers, conditions and approval flows. These references establish general features; they do not establish a configured invoice system. Use your chosen platform’s current official documentation. Save the four-way comparison and updated concept in AI Solution Concept and working artifact."], "think_prompt": "What is documented, what remains unverified, and what must be checked before your concept could be adopted?"}], "worked_case": {"label": "A routine invoice reminder meets a payment dispute", "setup": "FICTIONAL TRAINING EXAMPLE: A service company permits a standard reminder only when an invoice is seven days overdue, the unpaid balance and recipient are verified, and no dispute or payment arrangement is recorded. The accounts coordinator owns exception review and approval. A customer reports payment, but the record says unpaid. These are fictional company rules, not universal business requirements.", "evidence_table": [{"claim": "This task requires an AI agent.", "evidence": "The ordinary reminder has fixed rules. A checklist is the baseline; automation may suit repeated qualifying records.", "action": "Compare all four patterns. Choose based on the narrow task, inputs, oversight and consequences."}, {"claim": "An assistant drafted it, so it can send it.", "evidence": "Drafting and sending are separate actions. The bounded example grants drafting only.", "action": "Keep recipient, balance and wording review with the accounts coordinator; do not grant sending authority."}, {"claim": "No dispute flag means the reminder can proceed.", "evidence": "The customer reports payment, which contradicts unpaid status. Missing information does not resolve the conflict.", "action": "Stop the routine path, preserve both records and refer investigation to the accounts coordinator."}, {"claim": "The agent recommends a refund, so the refund is approved.", "evidence": "A recommendation supplies neither payment evidence nor approval from the authorized person.", "action": "Retain human decision and approval. No balance change, payment or refund occurs in practice."}], "revised_example": "Proposed bounded concept: use a checklist for o…2934 tokens truncated…kflow: [map]."}, {"type": "field", "id": "p2-j2-4-workflow", "label": "Existing workflow and the narrow step needing support", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-4-context", "label": "Reviewed communication and human approval points carried from Lesson 2.3", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-inputResult", "label": "Authorized input and the human-reviewed result", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-noAi", "label": "No AI — fit, limits, permissions and review effort", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-assistant", "label": "Assistant — fit, limits, permissions and review effort", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-automation", "label": "Rule-based automation — fit, limits, permissions and review effort", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-agent", "label": "Agent — fit, limits, permissions and review effort", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-aiComparison", "label": "AI comparison and the suggestion you accepted, revised or rejected", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-choice", "label": "Chosen support pattern", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-reason", "label": "Why this is sufficient and the other three are less suitable", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-allowed", "label": "Allowed actions and the authorized inputs they use", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-prohibited", "label": "Prohibited actions and access", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-checkpoints", "label": "Human checkpoints — owner, evidence checked and approval required", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-monitoring", "label": "Monitoring — named owner, review rhythm and signs of failure", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-stopFallback", "label": "Stop conditions and manual fallback for missing or contradictory data", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-documentation", "label": "Platform feature check — official page, URL, check date, supported claim and limits (or platform unselected; capabilities unverified)", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-4-concept", "label": "Updated solution concept with scope, input, result and human control", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-4-recommendOnly", "label": "One decision AI may recommend but may not approve, and its authorized approver", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-appliedCheck", "label": "Fictional invoice check — payment conflict, stopped action and human route", "hint": "", "lines": 7}, {"type": "field", "id": "p2-j2-4-limits", "label": "Remaining uncertainty and what must be checked before any adoption", "hint": "", "lines": 4}, {"type": "field", "id": "p2-j2-4-notes", "label": "Personal study notes and questions", "hint": "", "lines": 6}, {"type": "heading", "text": "Optional official documentation references"}, {"type": "text", "text": "Microsoft Learn — Triggers — https://learn.microsoft.com/en-us/power-automate/triggers-introduction — checked 2026-10-10. Triggers start flows; trigger conditions constrain runs."}, {"type": "text", "text": "Microsoft Learn — Conditions — https://learn.microsoft.com/en-us/power-automate/use-expressions-in-conditions — checked 2026-10-10. Conditions choose paths from evaluated inputs."}, {"type": "text", "text": "Microsoft Learn — Approval flows — https://learn.microsoft.com/en-us/power-automate/get-started-approvals — checked 2026-10-10. Approval workflows can request a human response."}, {"type": "text", "text": "Anthropic — Building effective agents — https://www.anthropic.com/engineering/building-effective-agents — checked 2026-10-10. Conceptual distinction between fixed workflows and dynamic agent steps; simplest sufficient approach. Historical tooling examples are not used as current capability claims."}, {"type": "note", "theme": "gold", "title": "Carry your concept into Lesson 2.5", "text": "Carry your support comparison, bounded solution concept and human checkpoints into Lesson 2.5: Build a Bounded Working Prototype. The next lesson opens according to its release schedule."}]}$workbook24$::jsonb),true),version=version+1,updated_at=now()
 where journey_number=2 and version=3 and jsonb_array_length(content->'pages')=3
 and md5((content->'pages')::text)='2f00e1cd5fe0cd702ece96522ce41ea7'
 and not exists(select 1 from jsonb_array_elements(content->'pages') p where p->>'lesson_id'='2.4');
 get diagnostics changed=row_count;
 if changed<>1 then raise exception 'Journey Two workbook changed or Lesson 2.4 page already exists'; end if;
end $install24$;
commit;
